<template>
  <section class="admin-container"><header class="admin-header"><div><p class="eyebrow">CONTROL ROOM / ADMIN</p><h1>Quản trị <em>LuNu.</em></h1><p>Quản lý kho nhạc Cloudinary, nội dung Supabase và quyền truy cập của thành viên.</p></div><div class="tab-buttons"><button :class="{ active: activeTab === 'songs' }" @click="activeTab = 'songs'">Kho nhạc <b>{{ songsList.length }}</b></button><button :class="{ active: activeTab === 'reports' }" @click="activeTab = 'reports'">Báo cáo <b>{{ openReportCount }}</b></button><button :class="{ active: activeTab === 'users' }" @click="activeTab = 'users'">Tài khoản <b>{{ usersList.length }}</b></button></div></header>
    <div v-if="errorMsg" class="admin-alert">{{ errorMsg }}</div>
    <div v-if="activeTab === 'songs'" class="admin-panel glass-panel"><div class="panel-heading"><div><span class="panel-kicker">IMPORT PIPELINE</span><h2>Thêm nhạc từ YouTube</h2></div><span class="status-dot">● ONLINE</span></div><div class="bulk-lyrics-card"><div class="panel-heading"><div><span class="panel-kicker">LYRICS BATCH</span><h2>Nhập lyrics hàng loạt</h2></div><div class="panel-actions"><button type="button" class="refresh-btn" @click="downloadLyricsTemplate" :disabled="!songsList.length">Tải mẫu 188 bài</button><button type="button" class="primary-btn" @click="handleBulkLyricsImport" :disabled="isBulkLyricsSaving || !bulkLyricsText.trim()">{{ isBulkLyricsSaving ? 'Đang cập nhật...' : 'Cập nhật lyrics' }}</button></div></div><p class="edit-note">Dùng JSON mẫu, điền lyrics không timestamp rồi dán lại vào đây. Hệ thống chỉ cập nhật cột <code>lyrics</code>; URL audio Cloudinary, mã bài và metadata khác được giữ nguyên.</p><textarea v-model="bulkLyricsText" class="bulk-lyrics-textarea" rows="7" placeholder="{\n  &quot;items&quot;: [\n    { &quot;id&quot;: &quot;uuid-cua-bai&quot;, &quot;lyrics&quot;: &quot;Nội dung lời bài hát...&quot; }\n  ]\n}"></textarea></div><DiscordBotSearch @song-added="refreshSongs" /><div class="panel-heading list-heading"><div><span class="panel-kicker">LIBRARY INDEX</span><h2>Danh sách nhạc hệ thống</h2></div><div class="panel-actions"><button class="refresh-btn" @click="restoreLegacy">↥ Khôi phục 188 bài</button><button class="refresh-btn" @click="refreshSongs">↻ Làm mới</button></div></div><div v-if="songsLoading" class="inline-state">Đang tải thư viện...</div><div v-else-if="!songsList.length" class="inline-state">Chưa có bài hát nào trong kho.</div><div v-else class="list-wrapper"><div v-for="song in songsList" :key="song.id" class="list-item"><div class="info"><img :src="song.cover || '/images/ChoCiu.jpg'" :alt="song.title" class="tiny-cover" /><div><strong>{{ song.title }}</strong><span>{{ song.artist || 'Unknown artist' }}</span><small class="media-key">{{ song.media_key || 'LEGACY / 188 GỐC' }}</small></div></div><div class="row-actions"><button type="button" @click.stop="findLyrics(song)" class="lyrics-btn" :disabled="isLyricsSearching" title="Tìm lyrics từ nguồn được hỗ trợ">Tìm lời</button><button type="button" @click.stop="startEdit(song)" class="edit-btn" title="Chỉnh sửa metadata bài hát">Sửa</button><button type="button" @click="handleDeleteSong(song.id)" class="delete-btn">Xóa</button></div></div></div></div>
    <Teleport to="body"><div v-if="editingSong && activeTab === 'songs'" class="edit-modal-backdrop" @click.self="cancelEdit"><section class="edit-song-panel glass-panel" role="dialog" aria-modal="true" aria-labelledby="edit-song-title" @click.stop><div class="panel-heading"><div><span class="panel-kicker">METADATA EDITOR</span><h2 id="edit-song-title">Chỉnh sửa bài hát</h2></div><button class="refresh-btn" type="button" @click="cancelEdit">Đóng</button></div><p class="edit-note">Bạn có thể đổi tên, ca sĩ, ảnh bìa hoặc lyrics. Link audio Cloudinary và mã bài vẫn được giữ nguyên.</p><form class="edit-song-form" @submit.prevent="saveSong"><label><span>TÊN BÀI HÁT</span><input v-model.trim="editMetadata.title" required maxlength="240" /></label><label><span>CA SĨ / NGHỆ SĨ</span><input v-model.trim="editMetadata.artist" required maxlength="160" /></label><label class="wide"><span>LYRICS</span><textarea v-model="editMetadata.lyrics" rows="5" maxlength="100000"></textarea></label><div class="form-actions"><button type="button" class="refresh-btn" @click="cancelEdit">Hủy</button><button type="submit" class="primary-btn" :disabled="isSongSaving">{{ isSongSaving ? 'Đang lưu...' : 'Lưu metadata' }}</button></div></form></section></div></Teleport>
    <Teleport to="body"><div v-if="lyricsSearchSong" class="lyrics-modal-backdrop" @click.self="closeLyricsPreview"><section class="lyrics-modal glass-panel" role="dialog" aria-modal="true" aria-labelledby="lyrics-modal-title" @click.stop><div class="panel-heading"><div><span class="panel-kicker">LYRICS REVIEW / LRCLIB</span><h2 id="lyrics-modal-title">Xem trước lời bài hát</h2><p class="lyrics-song-label">{{ lyricsSearchSong.title }} — {{ lyricsSearchSong.artist }}</p></div><button type="button" class="refresh-btn" @click="closeLyricsPreview">Đóng</button></div><p class="edit-note">Nguồn trả về có thể là bản plain lyrics hoặc đã được bỏ timestamp. Hãy kiểm tra nội dung và chọn đúng kết quả trước khi lưu.</p><div v-if="isLyricsSearching" class="lyrics-state"><span class="state-spinner">◌</span><p>Đang tìm lyrics...</p></div><div v-else-if="lyricsSearchError" class="lyrics-state"><span class="state-mark">!</span><p>{{ lyricsSearchError }}</p></div><div v-else-if="!lyricsCandidates.length" class="lyrics-state"><span class="state-mark">Aa</span><p>Không tìm thấy lyrics phù hợp cho bài này.</p></div><div v-else class="lyrics-candidates"><button v-for="candidate in lyricsCandidates" :key="candidate.provider_id || candidate.title" type="button" :class="['lyrics-candidate', { selected: selectedLyrics === candidate }]" @click="selectedLyrics = candidate"><strong>{{ candidate.title }}</strong><span>{{ candidate.artist }}<template v-if="candidate.album"> · {{ candidate.album }}</template></span></button></div><div v-if="selectedLyrics" class="lyrics-preview"><div class="lyrics-preview-meta"><span>{{ selectedLyrics.provider }}</span><a :href="selectedLyrics.source_url" target="_blank" rel="noreferrer">Mở nguồn</a></div><pre>{{ selectedLyrics.lyrics }}</pre></div><div class="form-actions"><button type="button" class="refresh-btn" @click="closeLyricsPreview">Hủy</button><button type="button" class="primary-btn" :disabled="isLyricsSaving || !selectedLyrics" @click="confirmLyrics">{{ isLyricsSaving ? 'Đang lưu...' : 'Xác nhận và lưu lyrics' }}</button></div></section></div></Teleport>
    <div v-if="activeTab === 'reports'" class="admin-panel glass-panel report-panel"><div class="panel-heading"><div><span class="panel-kicker">MODERATION DESK</span><h2>Report từ Chat</h2></div><span class="status-dot">{{ openReportCount }} ĐANG MỞ</span></div><p class="edit-note">Xem nội dung bị report, người gửi, lý do và quyết định xử lý. Report đã xử lý có thể được dọn định kỳ để giữ hệ thống nhẹ.</p><div class="report-toolbar"><select v-model="reportFilter" aria-label="Lọc trạng thái report" @change="refreshReports"><option value="">Tất cả report</option><option value="open">Đang mở</option><option value="reviewed">Đã xử lý</option><option value="dismissed">Đã bỏ qua</option></select><div class="panel-actions"><button type="button" class="refresh-btn" @click="refreshReports">↻ Làm mới</button><button type="button" class="refresh-btn danger-outline" @click="cleanupReports">Dọn report cũ</button></div></div><div v-if="reportsLoading" class="inline-state">Đang tải report...</div><div v-else-if="!reportsList.length" class="inline-state">Chưa có report phù hợp.</div><div v-else class="report-list"><article v-for="report in reportsList" :key="report.id" class="report-card" :class="`report-${report.status}`"><div class="report-topline"><div><span class="report-status">{{ reportStatusLabel(report.status) }}</span><strong>Report #{{ String(report.id).slice(0, 8) }}</strong></div><time>{{ formatReportTime(report.created_at) }}</time></div><div class="report-meta-grid"><div><span>NGƯỜI REPORT</span><strong>{{ reportUserLabel(report.reporter) }}</strong></div><div><span>NGƯỜI GỬI</span><strong>{{ reportUserLabel(report.sender) }}</strong></div><div class="report-reason"><span>LÝ DO</span><strong>{{ report.reason }}</strong></div></div><div class="reported-content"><span>NỘI DUNG BỊ REPORT</span><p>{{ report.message?.body || 'Tin nhắn đã bị xóa hoặc không còn nội dung.' }}</p><a v-if="report.message?.attachment_url" :href="report.message.attachment_url" target="_blank" rel="noopener noreferrer">↗ Mở attachment {{ report.message.attachment_name || '' }}</a></div><div v-if="report.status === 'open'" class="report-actions"><button type="button" class="review-btn" @click="reviewReport(report, 'reviewed')">✓ Đánh dấu đã xử lý</button><button type="button" class="dismiss-btn" @click="reviewReport(report, 'dismissed')">Bỏ qua report</button></div><div v-else class="reviewed-note">Đã cập nhật trạng thái: {{ formatReportTime(report.reviewed_at) }}</div></article></div></div>
    <div v-if="activeTab === 'users'" class="admin-panel glass-panel"><div class="panel-heading"><div><span class="panel-kicker">ACCESS MANAGEMENT</span><h2>Cấp tài khoản mới</h2></div></div><form @submit.prevent="handleAddUser" class="add-user-form"><label><span>TÊN ĐĂNG NHẬP</span><input v-model.trim="newUser.username" placeholder="member.name" required minlength="2" /></label><label><span>MẬT KHẨU</span><input v-model="newUser.password" type="password" placeholder="Tối thiểu 8 ký tự" required minlength="8" /></label><label><span>VAI TRÒ</span><select v-model="newUser.role"><option value="user">Member</option><option value="admin">Admin</option></select></label><button type="submit" class="primary-btn" :disabled="isSubmitting">{{ isSubmitting ? 'Đang lưu...' : 'Cấp quyền →' }}</button></form><p v-if="userMsg" class="success-msg">{{ userMsg }}</p><div class="panel-heading list-heading"><div><span class="panel-kicker">MEMBERS DIRECTORY</span><h2>Danh sách tài khoản</h2></div><button class="refresh-btn" @click="refreshUsers">↻ Làm mới</button></div><div class="list-wrapper"><div v-for="user in usersList" :key="user.id" class="list-item"><div class="user-row"><img v-if="user.avatar_url" :src="user.avatar_url" :alt="user.display_name || user.username" class="avatar avatar-image" /><div v-else class="avatar">{{ (user.display_name || user.username).slice(0,1).toUpperCase() }}</div><div><strong>{{ user.display_name || user.username }}</strong><span>@{{ user.username }} · {{ user.role === 'admin' ? 'Administrator' : 'Member' }}</span><small v-if="user.bio" class="user-bio">{{ user.bio }}</small></div></div><div class="row-actions"><button type="button" @click="startEditUser(user)" class="edit-btn">Sửa</button><button v-if="user.username !== 'admin'" @click="handleDeleteUser(user.id)" class="delete-btn">Thu hồi</button></div></div></div></div>
    <Teleport to="body"><div v-if="editingUser" class="edit-modal-backdrop" @click.self="cancelEditUser"><section class="edit-song-panel glass-panel" role="dialog" aria-modal="true" aria-labelledby="edit-user-title" @click.stop><div class="panel-heading"><div><span class="panel-kicker">USER PROFILE / ADMIN</span><h2 id="edit-user-title">Chỉnh sửa tài khoản</h2></div><button type="button" class="refresh-btn" @click="cancelEditUser">Đóng</button></div><p class="edit-note">Đang chỉnh sửa @{{ editingUser.username }}. Mật khẩu không hiển thị và không bị thay đổi ở màn hình này.</p><form class="edit-song-form" @submit.prevent="saveUserProfile"><label><span>TÊN HIỂN THỊ</span><input v-model.trim="editUserMetadata.display_name" maxlength="120" /></label><label><span>VAI TRÒ</span><select v-model="editUserMetadata.role"><option value="user">Member</option><option value="admin">Admin</option></select></label><label class="wide"><span>AVATAR URL</span><input v-model.trim="editUserMetadata.avatar_url" maxlength="1000" placeholder="https://..." /></label><label class="wide"><span>GIỚI THIỆU</span><textarea v-model="editUserMetadata.bio" maxlength="280" rows="4"></textarea></label><div class="form-actions"><button type="button" class="refresh-btn" @click="cancelEditUser">Hủy</button><button type="submit" class="primary-btn" :disabled="isUserSaving">{{ isUserSaving ? 'Đang lưu...' : 'Lưu hồ sơ' }}</button></div></form></section></div></Teleport>
  </section>
</template>

<script setup>
import { computed, onMounted, ref } from 'vue';
import DiscordBotSearch from '../components/DiscordBotSearch.vue';
import { getUsers, addUser, deleteUser, updateUserProfile, getSongs, deleteSong, updateSong, searchSongLyrics, updateSongLyricsBulk, importLegacySongs, getAdminChatReports, reviewAdminChatReport, cleanupAdminChatReports } from '../services/api';
import { loadSongs } from '../data/songs';
import { useDialog } from '../composables/useDialog';

const activeTab = ref('songs');
const songsList = ref([]); const usersList = ref([]); const reportsList = ref([]); const reportFilter = ref(''); const reportsLoading = ref(false); const userMsg = ref(''); const errorMsg = ref(''); const isSubmitting = ref(false); const songsLoading = ref(false);
const { confirmDialog } = useDialog();
const newUser = ref({ username: '', password: '', role: 'user' }); const editingUser = ref(null); const editUserMetadata = ref({ display_name: '', avatar_url: '', bio: '', role: 'user' }); const isUserSaving = ref(false); const editingSong = ref(null); const editMetadata = ref({ title: '', artist: '', cover: '', lyrics: '' }); const isSongSaving = ref(false); const bulkLyricsText = ref(''); const isBulkLyricsSaving = ref(false); const lyricsSearchSong = ref(null); const lyricsCandidates = ref([]); const selectedLyrics = ref(null); const lyricsSearchError = ref(''); const isLyricsSearching = ref(false); const isLyricsSaving = ref(false);
const restoreLegacy = async () => { if (!await confirmDialog('Khôi phục toàn bộ 188 bài hát vào Supabase? Các URL đã tồn tại sẽ được bỏ qua.', { title: 'Khôi phục thư viện', confirmLabel: 'Khôi phục', danger: false })) return; songsLoading.value = true; errorMsg.value = ''; try { const response = await importLegacySongs(); userMsg.value = response.message; await refreshSongs(); window.setTimeout(() => { userMsg.value = ''; }, 5000); } catch (error) { errorMsg.value = error.message; } finally { songsLoading.value = false; } };
const refreshSongs = async () => { songsLoading.value = true; errorMsg.value = ''; try { songsList.value = await getSongs(); await loadSongs(); } catch (error) { errorMsg.value = error.message; } finally { songsLoading.value = false; } };
const refreshUsers = async () => { errorMsg.value = ''; try { usersList.value = await getUsers(); } catch (error) { errorMsg.value = error.message; } };
const patchSongInView = (song) => { if (!song?.id) return; const index = songsList.value.findIndex((item) => String(item.id) === String(song.id)); if (index >= 0) songsList.value[index] = { ...songsList.value[index], ...song }; };
const startEdit = (song) => { editingSong.value = song; editMetadata.value = { title: song.title || '', artist: song.artist || '', cover: song.cover || '', lyrics: song.lyrics || '' }; }; const cancelEdit = () => { editingSong.value = null; }; const saveSong = async () => { if (!editingSong.value) return; isSongSaving.value = true; errorMsg.value = ''; try { const response = await updateSong(editingSong.value.id, editMetadata.value); patchSongInView(response.song || { ...editingSong.value, ...editMetadata.value }); userMsg.value = response.message || 'Đã cập nhật metadata bài hát.'; cancelEdit(); await loadSongs(); } catch (error) { errorMsg.value = error.message; } finally { isSongSaving.value = false; } };
const downloadLyricsTemplate = () => { const items = songsList.value.map((song) => ({ id: song.id, title: song.title, artist: song.artist || '', lyrics: '' })); const blob = new Blob([JSON.stringify({ items }, null, 2)], { type: 'application/json;charset=utf-8' }); const url = URL.createObjectURL(blob); const link = document.createElement('a'); link.href = url; link.download = 'lunu-188-lyrics-template.json'; link.click(); URL.revokeObjectURL(url); };
const handleBulkLyricsImport = async () => { errorMsg.value = ''; userMsg.value = ''; let parsed; try { parsed = JSON.parse(bulkLyricsText.value); } catch { errorMsg.value = 'JSON không hợp lệ. Hãy dùng file mẫu rồi chỉ điền nội dung vào trường lyrics.'; return; } const items = Array.isArray(parsed) ? parsed : parsed?.items; if (!Array.isArray(items) || !items.length) { errorMsg.value = 'JSON phải có dạng {"items":[{"id":"...","lyrics":"..."}]}.'; return; } const normalized = items.filter((item) => item && String(item.id || '').trim() && String(item.lyrics || '').trim()).map((item) => ({ id: String(item.id).trim(), lyrics: String(item.lyrics).trim() })); if (!normalized.length) { errorMsg.value = 'Chưa có mục lyrics nào có nội dung để cập nhật.'; return; } if (!await confirmDialog(`Cập nhật lyrics cho ${normalized.length} bài hát? URL Cloudinary sẽ không bị thay đổi.`, { title: 'Cập nhật lyrics hàng loạt', confirmLabel: 'Cập nhật', danger: false })) return; isBulkLyricsSaving.value = true; try { const response = await updateSongLyricsBulk(normalized); userMsg.value = response.message; bulkLyricsText.value = ''; (response.updated || []).forEach((song) => patchSongInView(song)); await loadSongs(); if (response.failed_count) errorMsg.value = response.failed.map((item) => `${item.id}: ${item.message}`).join(' | '); } catch (error) { errorMsg.value = error.message; } finally { isBulkLyricsSaving.value = false; } };
const findLyrics = async (song) => { lyricsSearchSong.value = song; lyricsCandidates.value = []; selectedLyrics.value = null; lyricsSearchError.value = ''; isLyricsSearching.value = true; errorMsg.value = ''; try { const response = await searchSongLyrics(song.id); lyricsCandidates.value = response.results || []; selectedLyrics.value = lyricsCandidates.value[0] || null; if (!lyricsCandidates.value.length) lyricsSearchError.value = response.message || 'Không tìm thấy lyrics phù hợp.'; } catch (error) { lyricsSearchError.value = error.message || 'Không thể tìm lyrics lúc này.'; } finally { isLyricsSearching.value = false; } };
const closeLyricsPreview = () => { lyricsSearchSong.value = null; lyricsCandidates.value = []; selectedLyrics.value = null; lyricsSearchError.value = ''; };
const confirmLyrics = async () => { if (!lyricsSearchSong.value || !selectedLyrics.value) return; isLyricsSaving.value = true; errorMsg.value = ''; try { const response = await updateSongLyricsBulk([{ id: lyricsSearchSong.value.id, lyrics: selectedLyrics.value.lyrics }]); if (response.failed_count) throw new Error(response.failed?.[0]?.message || 'Không thể lưu lyrics.'); const savedSong = lyricsSearchSong.value; patchSongInView({ id: savedSong.id, lyrics: selectedLyrics.value.lyrics }); userMsg.value = `Đã lưu lyrics cho “${savedSong.title}”.`; closeLyricsPreview(); await loadSongs(); } catch (error) { errorMsg.value = error.message; } finally { isLyricsSaving.value = false; } };
const handleDeleteSong = async (id) => { if (!await confirmDialog('Xóa bài hát này khỏi thư viện?', { title: 'Xóa bài hát', confirmLabel: 'Xóa bài hát', danger: true })) return; try { await deleteSong(id); await refreshSongs(); } catch (error) { errorMsg.value = error.message; } };
const handleAddUser = async () => { isSubmitting.value = true; errorMsg.value = ''; try { const response = await addUser(newUser.value.username, newUser.value.password, newUser.value.role); if (!response.success) throw new Error(response.message); userMsg.value = response.message; newUser.value = { username: '', password: '', role: 'user' }; await refreshUsers(); window.setTimeout(() => { userMsg.value = ''; }, 3000); } catch (error) { errorMsg.value = error.message; } finally { isSubmitting.value = false; } };
const handleDeleteUser = async (id) => { if (!await confirmDialog('Thu hồi tài khoản này?', { title: 'Thu hồi tài khoản', confirmLabel: 'Thu hồi', danger: true })) return; try { await deleteUser(id); await refreshUsers(); } catch (error) { errorMsg.value = error.message; } };
const openReportCount = computed(() => reportsList.value.filter((report) => report.status === 'open').length);
const reportUserLabel = (user) => user?.display_name || user?.username || 'Member';
const reportStatusLabel = (status) => status === 'reviewed' ? 'ĐÃ XỬ LÝ' : status === 'dismissed' ? 'ĐÃ BỎ QUA' : 'ĐANG MỞ';
const formatReportTime = (value) => { if (!value) return '—'; const date = new Date(value); return Number.isNaN(date.getTime()) ? '—' : date.toLocaleString('vi-VN', { dateStyle: 'short', timeStyle: 'short' }); };
const refreshReports = async () => { reportsLoading.value = true; errorMsg.value = ''; try { const response = await getAdminChatReports(reportFilter.value); reportsList.value = response.items || []; } catch (error) { errorMsg.value = error.message; } finally { reportsLoading.value = false; } };
const reviewReport = async (report, status) => { try { await reviewAdminChatReport(report.id, status); report.status = status; report.reviewed_at = new Date().toISOString(); userMsg.value = status === 'reviewed' ? 'Đã đánh dấu report đã xử lý.' : 'Đã bỏ qua report.'; } catch (error) { errorMsg.value = error.message; } };
const cleanupReports = async () => { if (!await confirmDialog('Dọn các report đã xử lý hoặc bỏ qua cũ hơn 30 ngày?', { title: 'Dọn report cũ', confirmLabel: 'Dọn report', danger: true })) return; try { const response = await cleanupAdminChatReports(30); userMsg.value = `Đã dọn ${response.deleted_count || 0} report cũ.`; await refreshReports(); } catch (error) { errorMsg.value = error.message; } };
const startEditUser = (user) => { editingUser.value = user; editUserMetadata.value = { display_name: user.display_name || user.username || '', avatar_url: user.avatar_url || '', bio: user.bio || '', role: user.role || 'user' }; };
const cancelEditUser = () => { editingUser.value = null; };
const saveUserProfile = async () => { if (!editingUser.value) return; isUserSaving.value = true; errorMsg.value = ''; try { const response = await updateUserProfile(editingUser.value.id, editUserMetadata.value); const index = usersList.value.findIndex((item) => String(item.id) === String(editingUser.value.id)); if (index >= 0) usersList.value[index] = response.user || { ...usersList.value[index], ...editUserMetadata.value }; userMsg.value = response.message || 'Đã cập nhật hồ sơ tài khoản.'; cancelEditUser(); window.setTimeout(() => { userMsg.value = ''; }, 3000); } catch (error) { errorMsg.value = error.message; } finally { isUserSaving.value = false; } };
onMounted(() => { refreshSongs(); refreshUsers(); refreshReports(); });
</script>

